def trans_blocks(grid, verbose=False):
 from collections import Counter
 h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]
 bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
 # contiguous bands of rows containing at least one foreground cell
 active=[any(v!=bg for v in row) for row in grid]
 blocks=[]; i=0
 while i<h:
  if not active[i]: i+=1; continue
  j=i+1
  while j<h and active[j]: j+=1
  blocks.append((i,j)); i=j
 totals=[sum(grid[r][c]!=bg for r in range(a,b) for c in range(w)) for a,b in blocks]
 best=[None]*len(blocks)
 maxshift=min(w//3,5)
 for ti,(ta,tb) in enumerate(blocks):
  opts=[]
  for si,(sa,sb) in enumerate(blocks):
   if si==ti or sb-sa != tb-ta or totals[si]<=totals[ti]: continue
   for sh in range(-maxshift,maxshift+1):
    eq=mf=miss=extra=ov=0
    for rr in range(tb-ta):
     s=grid[sa+rr]; t=grid[ta+rr]
     for c,v in enumerate(s):
      k=c+sh
      if 0<=k<w:
       ov+=1; tv=t[k]
       if v==tv: eq+=1
       if v!=bg and tv==v: mf+=1
       elif v!=bg and tv==bg: miss+=1
       elif v==bg and tv!=bg: extra+=1
    if miss>0 and extra==0 and mf>=2:
     opts.append(((eq,mf,totals[si],-abs(sh),-miss),si,sh,eq,mf,miss))
  if opts:
   opts.sort(reverse=True); _,si,sh,eq,mf,miss=opts[0]; best[ti]=(si,sh,eq,mf,miss)
 for ti,(ta,tb) in enumerate(blocks):
  if best[ti] is None: continue
  si,sh,*_=best[ti]; totalshift=sh; cur=si; seen={ti}
  while best[cur] is not None and cur not in seen:
   seen.add(cur); nsi,nsh,*_=best[cur]; totalshift+=nsh; cur=nsi
  sa,sb=blocks[cur]
  for rr in range(tb-ta):
   src=grid[sa+rr]; tgt=out[ta+rr]
   for c,v in enumerate(src):
    k=c+totalshift
    if 0<=k<w and v!=bg and tgt[k]==bg: tgt[k]=1
 if verbose: print('bg',bg,'blocks',blocks,'totals',totals,'best',best)
 return out
